from datetime import datetime
from pathlib import Path

parser = argparse.ArgumentParser(description="Install FOIMS-X local sandbox foundation with backup and rollback")
parser.add_argument("--root", required=True, type=Path)
args = parser.parse_args()
root = args.root.resolve()
work = root / "tools/doda_content_workbench"
preview = work / "doda_foims_x_preview.py"
model = work / "doda_foims_x_sandbox.py"
tests = work / "tests/test_foims_x_sandbox.py"
history = root / "docs/workbench/history/FOIMSX_Local_Sandbox_Foundation_2026-10-09.md"

def stop(message):
    raise SystemExit("STOP: " + message + " No project files were modified.")
if not preview.is_file(): stop("Preview file not found.")
raw = preview.read_bytes()
normalized = raw.decode("utf-8-sig").replace("\r\n", "\n")
if hashlib.sha256(normalized.encode()).hexdigest() != EXPECTED_SOURCE_SHA256:
    stop("The local preview differs from the uploaded version. Attach the current file; do not force this patch.")
for path in (model, tests, history):
    if path.exists(): stop(str(path) + " already exists. Verify the installed state instead of rerunning.")
    if not path.parent.is_dir(): stop("Missing directory: " + str(path.parent))
for name, text in ((preview, PREVIEW_TEXT), (model, MODEL_TEXT), (tests, TEST_TEXT)):
    compile(text, str(name), "exec")
backups = work / "backups"
numbers = [int(m.group(1)) for p in backups.iterdir() if p.is_dir() and (m := re.match(r"^v(\d+)_", p.name))] if backups.exists() else []
backup = backups / (f"v{max(numbers, default=71)+1:03d}_foimsx_sandbox_" + datetime.now().strftime("%Y%m%d_%H%M%S"))
target = backup / preview.relative_to(root)
target.parent.mkdir(parents=True, exist_ok=True)
target.write_bytes(raw)
if target.read_bytes() != raw: stop("Backup verification failed.")
(backup / "MANIFEST.txt").write_text(hashlib.sha256(raw).hexdigest() + "  " + preview.relative_to(root).as_posix() + "\n", encoding="utf-8")
history_text = """# FOIMS-X Local Sandbox Foundation - 2026-10-09

Desktop-only session model; opens paused at February 1, 1992. Play advances
one strategic minute per real second. Step requires pause; reset stays paused.
Pause and resume do not charge paused time. Rendering only reads snapshots.
Session metrics are copied from catalog defaults. Available/lifetime Evidence
start from STARTING_EVIDENCE (900 fallback). Funding is explicitly unconfigured.
Refresh reloads authoring tables, not session values; Reset Session re-seeds them.
The existing CRT layout, assets and legacy clock conversion helper are retained.
No time-driven metric drift, tasks, missions, payroll, or budget reviews yet.
No source CSV writes, native calls, game changes or save persistence.
Added 12 headless model tests. HQ-only in-game access remains a later milestone.
"""
crlf = b"\r\n" in raw
body = PREVIEW_TEXT.replace("\n", "\r\n") if crlf else PREVIEW_TEXT
writes = {preview: (b"\xef\xbb\xbf" if raw.startswith(b"\xef\xbb\xbf") else b"") + body.encode(),
          model: MODEL_TEXT.encode(), tests: TEST_TEXT.encode(), history: history_text.encode()}
source = root / "data_authoring/source"
before = {p: p.read_bytes() for p in source.glob("*.csv")}

def rollback():
    preview.write_bytes(raw)
    for path in (model, tests, history): path.unlink(missing_ok=True)

print("=== COPY FROM HERE ===", flush=True)
print("Backup folder:", backup, flush=True)
try:
    for path, data in writes.items(): path.write_bytes(data)
    suite = subprocess.run([sys.executable, "-m", "unittest", "discover", "-s", "tests"], cwd=work,
                           stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, errors="replace")
    print(suite.stdout, flush=True)
    if suite.returncode:
        raise RuntimeError("Full test suite failed")
    if any(p.read_bytes() != data for p, data in before.items()) or set(source.glob("*.csv")) != set(before):
        raise RuntimeError("Source CSV changes detected during tests; inspect them separately")
except BaseException:
    rollback()
    print("PATCH ROLLED BACK: original preview restored; new model, tests and note removed.", flush=True)
    raise
print("Source CSVs unchanged. Expected test total if baseline was 339: 351", flush=True)
print("RESULT: PASS. Restart Workbench and open FOIMS-X Preview.", flush=True)
